// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 initialSum, uint256 deposit) public {
        // Restrict to the domain where the bug can manifest: we need a starting balance
        // high enough that adding deposit overflows, and deposit non-zero so the bug
        // is distinct from a no-op.
        // The reference ensures invariant: sum(Acc[i].balance) <= address(c).balance
        // We can check this for a single user to keep it simple:
        // After Put, Acc[user].balance <= address(c).balance
        address user = address(uint160(uint256(keccak256(abi.encode(initialSum)))));
        uint256 start = bound(initialSum, 0, type(uint256).max);
        uint256 add = bound(deposit, 1, type(uint256).max);

        // Pre-populate the user's balance by artificially setting the contract balance
        // via a self-destruct helper, then calling Put with start amount.
        // Wait, we can't call selfdestruct or use vm.store. Instead, we can set a
        // high balance for the user by making multiple calls from other accounts,
        // but the simplest way to get a controlled high balance is to use a helper
        // that supplies the ether. Actually, we can just use vm.deal on the test contract
        // and call Put to increase the balance gradually, but to reach a near-overflow
        // value we'd need 2^256-1 / 2 calls, which is impossible.
        // The fuzzer can't reasonably reach overflow without setting an already huge
        // balance, which can only be done via vm.deal + Put in a loop, which is impractical.
        // Therefore, we need a different invariant that doesn't require overflow to be
        // pre-set, but still detects the bug's presence.
        //
        // Observation: The bug removes the overflow check. Without the check, if the
        // balance overflows, it wraps to a small number. The invariant: after any Put,
        // acc.balance >= msg.value (since it added it to a non-negative previous balance).
        // In the buggy version, if overflow occurs, acc.balance could be less than the
        // value sent due to wrapping. Let's verify:
        // In correct version: acc.balance >= msg.value (previous balance >=0, so
        // balance + msg.value >= msg.value).
        // In buggy version: if overflow, new_balance = (prev + msg.value) mod 2^256,
        // which could be < msg.value (e.g., prev = 2^256-10, msg.value = 20, new_balance = 10).
        // So the property is: after Put, the user's Acc[user].balance >= msg.value.
        // The correct version ensures this by reverting on overflow (require).
        // The buggy version fails this for some input.
        //
        // However, we cannot easily set the previous balance to near overflow without
        // using vm.store (forbidden) or an enormous number of transactions.
        // But we can use a helper to self-destruct sending ether to the contract, and
        // call Put. Wait, a selfdestruct sends only raw ether without updating Acc mappings.
        // That doesn't help set the mapping.
        //
        // Alternative: Use a reentrant call? No.
        //
        // Since the fuzzer can't directly set storage, we need a test that can trigger
        // overflow through the contract's own logic. The only way to increase a balance
        // is via Put or the fallback. So overflow will only occur after enough calls accumulate.
        // The fuzzer might not be able to do that in one test call.
        //
        // Maybe the simplest invariant is: For any user, after a Put call that does not
        // revert, Acc[user].balance is strictly greater than the previous balance
        // (since msg.value > 0). In the buggy version, overflow causes balance to
        // decrease. We can test this by calling Put twice: first with a value v1,
        // then with v2, and checking that after the second call, the new balance is
        // > the balance after the first call (or at least >= initial + v2).
        // But we can't guarantee overflow occurs for the fuzzer unless we can set
        // initial balance to near max. Since we can't, this invariant won't be
        // violated by the buggy version unless overflow actually happens.
        //
        // The key insight: The fuzzer can generate inputs that would cause overflow
        // IF the balance were already high, but since the balance is always starting
        // from zero in a fresh contract, overflow never happens. Thus the fuzzer
        // won't find a distinguishing input using the actual state because the bug
        // only manifests when an overflow occurs, which requires a pre-existing
        // large balance that the fuzzer cannot create without vm.store or many
        // transactions (which a single call can't do).
        //
        // Therefore, the test must directly set up a near-overflow balance by using
        // a helper that self-destructs to fund the contract, and also sets the
        // storage mapping via a low-level call? No, vm.store is forbidden.
        //
        // The only allowed way to set storage is through the contract's public
        // functions. So we are back to the same problem.
        //
        // Perhaps the intended invariant is something that doesn't require overflow
        // to happen, but reflects the presence/absence of the check itself.
        // The require statement is: require(((acc.balance + msg.value) >= acc.balance));
        // This is equivalent to: require(acc.balance + msg.value >= acc.balance).
        // Since msg.value > 0, this is always true unless overflow occurs.
        // So the check only rejects inputs that cause overflow.
        //
        // In the reference, if overflow would happen, it reverts, preserving the
        // invariant. In the buggy, it doesn't revert and allows overflow.
        // To detect the difference without actually overflowing (since we can't),
        // we can check that the reference NEVER reverts for any call that doesn't
        // overflow (since the check is trivially true), while the buggy behaves
        // identically. That wouldn't fail the buggy either.
        //
        // So the only way to distinguish is to actually cause an overflow scenario.
        // Since we can't set storage directly, we might use a pre-deployed helper
        // that receives ether and calls back? No, reentrancy doesn't affect balance.
        //
        // Gas limits? No.
        //
        // What about using a large number of calls within a single transaction?
        // We could write an attacker contract that calls Put many times in a loop.
        // But the fuzzer doesn't control that; we can deploy such a helper.
        // The fuzzer would provide parameters (like number of iterations, value per call).
        // That would allow the helper to increment the balance to a near-overflow
        // value, and then the final Put can cause overflow.
        // Let's design:
        // Helper contract has a function attack(address cAddr, uint256 n, uint256 value) that
        // calls c.Put{value: value}() n times. Then, after that, we call Put once more
        // with a carefully chosen value that causes overflow.
        // But the fuzzer parameters are the values passed to testFuzz_property.
        // We can make the fuzzer provide n, value, finalValue.
        // However, the helper is allowed because it embodies the adversarial
        // counterparty behavior: an external caller that interacts with C in a way
        // that exposes the difference.
        // The invariant tested could be: after a sequence of Puts (via helper) and
        // a final Put, the Acc[helper] balance should be >= the sum of all values
        // sent (modulo overflow?). Actually, we could just assert that the final
        // Put never reverts unless expected? But we want a property that passes
        // reference and fails buggy.
        // We could assert: after the operations, the contract's balance equals the
        // sum of Acc balances (since no withdrawals). The reference maintains this
        // because it never overflows (reverts if it would), while the buggy may
        // break it if overflow occurs.
        // So: invariant = address(c).balance == sum of all Acc balances.
        // We can iterate over a known set of accounts used.
        // The fuzzer provides: n (iterations), value (per iteration), finalValue.
        // Helper calls Put n times with value, then one last Put with finalValue.
        // Then we check sum of balances of all involved accounts (helper and maybe
        // others) against address(c).balance.
        // This seems feasible and uses only allowed cheatcodes (vm.deal to fund
        // the helper, vm.assume to avoid zero values).
        //
        // But wait: the invariant "sum of all balances == contract balance" holds
        // for reference only if no overflow occurs; but the reference reverts on
        // overflow, so for the reference, the overflow-causing transaction fails,
        // and the invariant holds after the successful transactions. For the buggy,
        // overflow doesn't revert, so the sum of balance (with overflow) may not
        // match contract balance (since balance wraps but actual ether doesn't).
        // So the reference will pass because the overflow attempt is a revert,
        // leaving the state consistent; the buggy will fail because the invoke is
        // not a revert and state becomes inconsistent.
        //
        // Implementation:
        // - Deploy a helper Attacker with a function that calls Put n times.
        // - Fund the helper with enough ether (value * n + finalValue).
        // - Call helper.attack(c, n, value), then helper.finalPut(c, finalValue).
        // - Then sum Acc balances of helper and any other accounts used (maybe c itself).
        // - Assert sum == address(c).balance.
        //
        // But we must be careful: the helper is an adversarial counterparty that
        // interacts with C. The fuzzer provides n, value, finalValue.
        // We also need to ensure that n * value doesn't overflow uint256 before
        // calling, but we can bound them reasonably.
        //
        // Additionally, we need to consider that the reference may revert on the
        // final Put if it causes overflow. That's fine because the assert will
        // check after the final call; if it reverts, we catch it and skip or
        // assert true because the reference still holds the invariant (no state
        // change). To make the test work in both cases, we should use a try/catch
        // for the final Put, and then after all operations, assert the invariant
        // holds on the current state. The reference will only revert the final
        // Put if overflow, so after that, the state remains consistent. The buggy
        // will not revert, but its state becomes inconsistent. So the invariant
        // check after all calls should pass for reference regardless of revert,
        // and fail for buggy if overflow occurred.
        //
        // However, we need to ensure that the sequence of operations actually
        // causes overflow in the buggy case; the fuzzer must choose n, value,
        // finalValue such that n*value is near max, and n*value + finalValue
        // overflows. Since the fuzzer can search over n and value, it can find
        // such values (e.g., n=2, value=2**255, finalValue=2**255).
        // We'll bound n and value to reasonable ranges to allow that.
        //
        // Let's design the test.
    }
}

contract Attacker {
    function attack(address c, uint256 n, uint256 val) external payable {
        for (uint256 i = 0; i < n; i++) {
            (bool success, ) = c.call{value: val}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
            require(success, "Put call failed");
        }
    }
}

