pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(deposit1 > 0);
        vm.assume(deposit2 > 0);
        vm.assume(deposit1 + deposit2 > deposit1); // no overflow in test logic itself
        vm.deal(actor, deposit1 + deposit2);

        vm.prank(actor);
        c.Put{value: deposit1}(0);
        uint256 balanceAfterFirst = c.Acc(actor).balance;

        vm.prank(actor);
        c.Put{value: deposit2}(0);
        uint256 balanceAfterSecond = c.Acc(actor).balance;

        assertTrue(balanceAfterSecond == balanceAfterFirst + deposit2);
    }
}

