pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, address caller) public {
        // Keep _unlockTime in a sensible range that includes future, past and current timestamps.
        // bound to a range that is safe for block.timestamp arithmetic and the require check.
        _unlockTime = bound(_unlockTime, 1, 2**64 - 1);
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        // Deal some ether so Put can be called with a non-zero value.
        vm.deal(caller, 1 ether);
        // Warp to a known block.timestamp so _unlockTime can be compared relative to it.
        uint256 currentTime = 1_700_000_000;
        vm.warp(currentTime);
        // Call Put from the fuzzed caller with a fuzzed _unlockTime.
        vm.prank(caller);
        c.Put{value: 1 ether}(_unlockTime);
        // Read the stored unlockTime for the caller.
        (uint256 storedUnlockTime,) = c.Acc(caller);
        // The rule: storedUnlockTime must be >= currentTime, and if _unlockTime > currentTime then storedUnlockTime must equal _unlockTime.
        bool ruleSatisfied = (storedUnlockTime >= currentTime) &&
                             ((_unlockTime > currentTime) ? storedUnlockTime == _unlockTime : true);
        assertTrue(ruleSatisfied);
    }
}

