pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, address caller) public {
        // 1. restrict to admissible domain: amount > 0 and caller != address(0)
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        // ensure unlockTime is not so large that it causes overflow in block.timestamp comparison
        unlockTime = bound(unlockTime, 0, type(uint256).max - 365 days);

        // 2. set up: give caller ether and warp if necessary, then call Put
        vm.deal(caller, amount);
        vm.prank(caller);
        c.Put{value: amount}(unlockTime);

        // 3. assert: the stored unlockTime must be >= the supplied unlockTime
        //    (the correct contract sets acc.unlockTime = max(_unlockTime, block.timestamp);
        //     the mutant never updates unlockTime, so an older unlockTime may persist)
        assertTrue(c.Acc(caller).unlockTime >= unlockTime);
    }
}

