pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _initialUnlockTime, uint112 _amount) public {
        // Bound to admissible domain
        vm.assume(_initialUnlockTime <= type(uint64).max);
        vm.assume(_unlockTime <= type(uint64).max);
        vm.assume(_unlockTime > _initialUnlockTime); // ensure the new unlock time is greater than the old one
        _amount = uint112(bound(_amount, 1, type(uint112).max));

        // Setup: prank an arbitrary user and call Put with the initial unlock time and then with the new unlock time
        address user = address(uint160(_amount) ^ 0xdead);
        vm.deal(user, _amount);
        vm.startPrank(user);
        c.Put{value: _amount}(_initialUnlockTime);
        c.Put{value: _amount}(_unlockTime);
        vm.stopPrank();

        // After the second Put, the user's unlockTime must equal the new _unlockTime (assuming block.timestamp <= _unlockTime)
        // Since _unlockTime is bounded to be > _initialUnlockTime and we warp to a point earlier than _unlockTime,
        // the correct contract should update unlockTime to _unlockTime; the mutant leaves it at _initialUnlockTime.
        vm.warp(1); // ensure block.timestamp is less than _unlockTime
        assertTrue(c.Acc(user).unlockTime == _unlockTime);
    }
}
