    C c;
    constructor(C _c) { c = _c; }
    function run(uint unlockTime, uint am) public payable {
        require(true);
        // setup: deposit exactly MinSum with a future unlockTime
        uint min = c.MinSum();
        require(address(this).balance >= min);
        c.Put{value: min}(unlockTime);
        // advance time so that block.timestamp > unlockTime (needs evm_increaseTime cheatcode, not allowed)
        // Instead, rely on Put's unlockTime logic: it sets unlockTime to max(_unlockTime, block.timestamp)
        // If we pass unlockTime = block.timestamp, then block.timestamp > unlockTime will be false.
        // We must ensure block.timestamp > unlockTime. Use a future block? Not possible without cheatcodes.
        // Call Collect when balance == MinSum.
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

