// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 initialBalance, uint256 unlockTime, uint256 withdrawAmount) public {
        // Ensure the balance is exactly MinSum and the unlockTime is in the past
        initialBalance = bound(initialBalance, 1 ether, 1 ether);
        unlockTime = bound(unlockTime, 1, block.timestamp - 1);
        withdrawAmount = bound(withdrawAmount, 1, initialBalance);

        address user = address(0x1000);
        vm.deal(user, initialBalance);
        vm.prank(user);
        c.Put{value: initialBalance}(unlockTime);

        uint256 balanceBefore = address(c).balance;
        vm.prank(user);
        c.Collect(withdrawAmount);
        uint256 balanceAfter = address(c).balance;

        // After a successful Collect, the contract's balance should decrease by withdrawAmount
        // In the reference contract, the condition acc.balance>=MinSum allows Collect when balance equals MinSum
