pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount, uint256 warpForward) public {
        // Keep in admissible domain: positive amounts, unlockTime in the future relative to initial timestamp
        vm.assume(putAmount > 0 && putAmount <= type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= type(uint128).max);
        vm.assume(warpForward <= 365 days);
        // Make unlockTime some reasonable future
        uint256 start = block.timestamp;
        vm.assume(unlockTime > start && unlockTime <= start + 365 days);

        // Deploy an adversarial counterparty that always reverts on receiving Ether,
        // making the low-level call inside Collect fail. This ensures that a Collect
        // that attempts transfer before the unlock time will revert because the transfer
        // fails, whereas the correct contract's time check prevents the transfer entirely.
        Reverter adv = new Reverter();

        // Setup: fund the adversarial address
        vm.deal(address(adv), 0);

        // Put funds into the contract with the adversarial address as actor,
        // setting unlockTime.
        vm.deal(address(adv), putAmount);
        vm.prank(address(adv));
        c.Put{value: putAmount}(unlockTime);

        // Warp to a time before unlockTime
        uint256 preCollectTime = start + warpForward;
        if (preCollectTime >= unlockTime) {
            vm.assume(false); // skip this case; fuzzer will find pre-unlock times
        }
        vm.warp(preCollectTime);

        // The collected amount must be ≤ available balance and ≥ MinSum (1 ether) for condition
        uint256 bal = c.Acc(address(adv)).balance;
        vm.assume(collectAmount <= bal && collectAmount >= 1 ether);

        // Attempt Collect via the adversarial address, which will revert on receiving Ether
        vm.prank(address(adv));
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Invariant: For a call that attempts to transfer Ether to a failing receiver,
        // the Collect call must never succeed when block.timestamp <= unlockTime.
        // The correct contract rejects due to time check, so low-level revert is irrelevant.
        // The mutant misses the time check, performs the transfer, hits the revert, and propagates
        // the revert. However, if the mutant's balance reduction happens before the failed transfer,
        // the invariant about state change could be different. This test checks the "no successful transfer before unlock"
        // property from the external perspective.
        assertTrue(!ok, "Collect succeeded before unlockTime -> invariant violation");
    }
}

