contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public payable {
        require(putAmount > 0);
        require(address(this).balance >= putAmount);
        // Put funds as sender
        c.Put{value: putAmount}(unlockTime);
        // Now try to collect as sender
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        assert(reverted || (c.Acc(sender).balance >= c.MinSum()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 _am, uint256 unlockTime, uint256 putValue, uint256 collectAmt) public payable {
        require(true);
        // set up caller state: put ether to set balance and unlockTime
        c.Put{value: putValue}(unlockTime);
        // send ether from caller? No, we are the test contract; we can impersonate by calling Put and Collect ourselves?
        // Actually, the test contract itself acts as the user. So we need to set up our own state.
        // We already called Put, which gives us balance.
        // Now try Collect with a given amount.
        bool reverted;
        try c.Collect(collectAmt) { reverted = false; } catch { reverted = true; }
        assert(!reverted || address(c).balance >= c.MinSum());
    }
    receive() external payable {}
}
